/**
 * Swap a person with the one above them in the list (up) or below them (down); refused for the top
 * person moving up and the bottom one moving down. PERSON_MOVED carries their new position, counting
 * from 1.
 */
@Transactional
public Person move(String sheetId, String user, long personId, boolean up) {
    List<Person> listed = new ArrayList<>(people.findBySheetIdOrderByPositionAscIdAsc(sheetId));
    int at = -1;
    for (int i = 0; i < listed.size(); i++) {
        if (listed.get(i).getId() == personId) {
            at = i;
        }
    }
    if (at < 0) {
        throw new ResponseStatusException(HttpStatus.NOT_FOUND, "No such person on this sheet.");
    }
    int to = up ? at - 1 : at + 1;
    if (to < 0 || to >= listed.size()) {
        throw new ResponseStatusException(HttpStatus.CONFLICT,
                up ? "The top person cannot move up." : "The bottom person cannot move down.");
    }
    java.util.Collections.swap(listed, at, to);
    for (int i = 0; i < listed.size(); i++) {
        Person each = listed.get(i);
        if (each.getPosition() != i + 1) {
            each.setPosition(i + 1);
            people.save(each);
        }
    }
    people.flush();
    Person moved = listed.get(to);
    audit.recordOnCommit("PERSON_MOVED sheet=" + sheetId + " by=" + user
            + " name=" + moved.getName() + " position=" + (to + 1));
    return moved;
}

    }
    return tree;
}

/**
 * Change the sheet's today, auditing the figures that moves. When it moves, each person's due-total
 * as it stood on the day being left is audited first, in list order, and the sheet as it stood at
 * the end of that day is kept (see {@link TodayLeaving}). The periods it puts past their grace
 * days are closed (see {@link TodayChanged}) before those figures are audited.
 */
@Transactional
public synchronized Sheet setToday(String id, String user, LocalDate today) {
    Sheet sheet = load(id);
    Rollups.Rollup before = rollups.take(id);
    if (!today.equals(sheet.getToday())) {
        before.people().values().forEach(figures -> audit.recordOnCommit("SNAPSHOT sheet=" + id + " by=" + user
                + " name=" + figures.name() + " due-total=" + Rollups.shown(figures.dueTotal())));
        events.publishEvent(new TodayLeaving(id, sheet.getToday()));
    }
    sheet.setToday(today);
    Sheet saved = sheets.saveAndFlush(sheet);
    events.publishEvent(new TodayChanged(id, user, today, saved.getGraceDays()));
    rollups.audit(id, user, before);
    return saved;
}

/** Whether the sheet is archived: nothing on it may change. */
@Transactional(readOnly = true)
public boolean archived(String id) {
    return sheets.findById(id).map(Sheet::isArchived).orElse(false);
}

